    let received_clone = received_artifacts.clone();
    tokio::spawn(async move {
        while let Ok(evt) = event_rx.recv().await {
            if let AgentEvent::ArtifactCreated { .. } = evt {
                received_clone.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
