use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ArtifactKind {
    Code,
    Document,
    Image,
    Patch,
    Automation,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Artifact {
    pub id: String,
    pub session_id: String,
    pub title: String,
    pub kind: ArtifactKind,
    pub summary: String,
    pub payload: ArtifactPayload,
    pub created_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", content = "data", rename_all = "snake_case")]
pub enum ArtifactPayload {
    Code {
        language: String,
        framework: Option<String>,
        entry_file: Option<String>,
        files: Vec<ArtifactFile>,
    },
    Document {
        doc_type: String, // PRD, Architecture, Report, Meeting Notes
        markdown: String,
        size_bytes: usize,
    },
    Image {
        prompt: String,
        width: u32,
        height: u32,
        file_path: Option<String>,
        preview_url: Option<String>,
        size_bytes: usize,
        model: String,
    },
    Patch {
        git_target: String,
        diff: String,
        files_changed: usize,
        additions: usize,
        deletions: usize,
    },
    Automation {
        trigger: String,
        schedule: Option<String>,
        action: String,
        is_active: bool,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ArtifactFile {
    pub path: String,
    pub content: String,
}

impl Artifact {

pub fn new_code(
    session_id: impl Into<String>,
    title: impl Into<String>,
    summary: impl Into<String>,
    language: impl Into<String>,
    framework: Option<String>,
    files: Vec<ArtifactFile>,
) -> Self {
    Self {
        id: Uuid::new_v4().to_string(),
        session_id: session_id.into(),
        title: title.into(),
        kind: ArtifactKind::Code,
        summary: summary.into(),
        payload: ArtifactPayload::Code {
            language: language.into(),
            framework,
            entry_file: files.first().map(|f| f.path.clone()),
            files,
        },
        created_at: Utc::now(),
    }
}

pub fn new_document(
    session_id: impl Into<String>,
    title: impl Into<String>,
    doc_type: impl Into<String>,
    markdown: impl Into<String>,
) -> Self {
    let doc_type = doc_type.into();
    let md = markdown.into();
    let bytes = md.len();
    Self {
        id: Uuid::new_v4().to_string(),
        session_id: session_id.into(),
        title: title.into(),
        kind: ArtifactKind::Document,
        summary: format!("{} ({} KB)", doc_type, bytes / 1024),
        payload: ArtifactPayload::Document {
            doc_type,
            markdown: md,
            size_bytes: bytes,
        },
        created_at: Utc::now(),
    }
}

pub fn new_image(
    session_id: impl Into<String>,
    title: impl Into<String>,
    prompt: impl Into<String>,
    width: u32,
    height: u32,
    model: impl Into<String>,
    file_path: Option<String>,
    preview_url: Option<String>,
    size_bytes: usize,
) -> Self {
    let model = model.into();
    Self {
        id: Uuid::new_v4().to_string(),
        session_id: session_id.into(),
        title: title.into(),
        kind: ArtifactKind::Image,
        summary: format!("{}x{} Image - {}", width, height, model),
        payload: ArtifactPayload::Image {
            prompt: prompt.into(),
            width,
            height,
            file_path,
            preview_url,
            size_bytes,
            model,
        },
        created_at: Utc::now(),
    }
}

    pub fn new_patch(
        session_id: impl Into<String>,
        title: impl Into<String>,
        git_target: impl Into<String>,
        diff: impl Into<String>,
        files_changed: usize,
        additions: usize,
        deletions: usize,
    ) -> Self {
        Self {
            id: Uuid::new_v4().to_string(),
            session_id: session_id.into(),
            title: title.into(),
            kind: ArtifactKind::Patch,
            summary: format!("+{} -{} lines ({} files)", additions, deletions, files_changed),
            payload: ArtifactPayload::Patch {
                git_target: git_target.into(),
                diff: diff.into(),
                files_changed,
                additions,
                deletions,
            },
            created_at: Utc::now(),
        }
    }
}

use serde::{Deserialize, Serialize};
use tokio::sync::broadcast;

use crate::artifact::Artifact;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum AgentState {
    Idle,
    Thinking,
    CallingTool,
    AwaitingApproval,
    ExecutingTool,
    GeneratingArtifact,
    Completed,
    Failed,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", content = "payload", rename_all = "snake_case")]
pub enum AgentEvent {
    StateChanged {
        session_id: String,
        state: AgentState,
    },
    TextDelta {
        session_id: String,
        delta: String,
    },
    ThoughtDelta {
        session_id: String,
        delta: String,
    },
    ToolCallStarted {
        session_id: String,
        call_id: String,
        tool_name: String,
        arguments: serde_json::Value,
    },
    ToolCallFinished {
        session_id: String,
        call_id: String,
        output: serde_json::Value,
        is_error: bool,
    },
    ArtifactCreated {
        session_id: String,
        artifact: Artifact,
    },
    ApprovalRequested {
        session_id: String,
        approval_id: String,
        tool_name: String,
        risk_tier: u8,
        description: String,
    },
    ApprovalResolved {
        session_id: String,
        approval_id: String,
        /// "approved" | "rejected" | "expired"
        decision: String,
    },
    SteerApplied {
        session_id: String,
        steer_id: String,
        text: String,
    },
    RelayLog {
        channel: String, // "telegram", "whatsapp", "desktop"
        message: String,
        is_ok: bool,
        timestamp: i64,
    },
    Error {
        session_id: String,
        message: String,
    },
}

pub type EventSender = broadcast::Sender<AgentEvent>;

pub type EventReceiver = broadcast::Receiver<AgentEvent>;

pub fn create_event_bus(capacity: usize) -> (EventSender, EventReceiver) {
    broadcast::channel(capacity)
}

