use crate::trait_def::{ChatRequest, ModelProvider};

#[derive(Clone, Copy, PartialEq, Eq)]
enum AuthMode {
    ApiKey,
    Bearer,
}

pub struct AnthropicProvider {
    client: reqwest::Client,
    api_key: String,
    base_url: String,
    label: String,
    auth_mode: AuthMode,
    extra_headers: HeaderMap,
    default_max_tokens: u32,
}

impl AnthropicProvider {
    pub fn new(api_key: impl Into<String>) -> Self {
        Self {
            client: reqwest::Client::new(),
            api_key: api_key.into(),
            base_url: "https://api.anthropic.com/v1".to_string(),
            label: "anthropic".to_string(),
            auth_mode: AuthMode::ApiKey,
            extra_headers: HeaderMap::new(),
            default_max_tokens: 4096,
        }
    }

    pub fn with_base_url(api_key: impl Into<String>, base_url: impl Into<String>) -> Self {
        Self {
            client: reqwest::Client::new(),
            api_key: api_key.into(),
            base_url: base_url.into(),
            label: "anthropic".to_string(),
            auth_mode: AuthMode::ApiKey,
            extra_headers: HeaderMap::new(),
            default_max_tokens: 4096,
        }
    }

    /// Anthropic-compatible endpoints such as GitHub Copilot's `/v1/messages`
    /// authenticate with a bearer token instead of `x-api-key`.
    pub fn with_bearer_auth(api_key: impl Into<String>, base_url: impl Into<String>) -> Self {
        let mut provider = Self::with_base_url(api_key, base_url);
        provider.auth_mode = AuthMode::Bearer;
        provider
    }

    pub fn with_label(mut self, label: impl Into<String>) -> Self {
        self.label = label.into();
        self
    }

    pub fn with_extra_headers(mut self, headers: HeaderMap) -> Self {
        for (name, value) in headers.iter() {
            self.extra_headers.insert(name.clone(), value.clone());
        }
        self
    }

    pub fn with_default_max_tokens(mut self, max_tokens: u32) -> Self {
        self.default_max_tokens = max_tokens;
        self
    }
}

#[async_trait]
impl ModelProvider for AnthropicProvider {
    fn provider_name(&self) -> &str {
        &self.label
    }

    async fn stream_chat(
        &self,
        request: ChatRequest,
        event_sender: Sender<StreamEvent>,
        cancellation: CancellationToken,
    ) -> Result<()> {
        let endpoint = format!("{}/messages", self.base_url.trim_end_matches('/'));

        let mut headers = HeaderMap::new();
        headers.insert(CONTENT_TYPE, HeaderValue::from_static("application/json"));
        match self.auth_mode {
            AuthMode::ApiKey => {
                headers.insert(
                    "x-api-key",
                    HeaderValue::from_str(&self.api_key)
                        .map_err(|e| OdonError::Auth(format!("Invalid Anthropic API key format: {e}")))?,
                );
            }
            AuthMode::Bearer => {
                headers.insert(
                    AUTHORIZATION,
                    HeaderValue::from_str(&format!("Bearer {}", self.api_key))
                        .map_err(|e| OdonError::Auth(format!("Invalid bearer token format: {e}")))?,
                );
            }
        }
        headers.insert("anthropic-version", HeaderValue::from_static("2023-06-01"));
        for (name, value) in self.extra_headers.iter() {
            headers.insert(name.clone(), value.clone());
        }
        if request
            .messages
            .iter()
            .any(|m| m.content.attachments.iter().any(|a| a.mime_type == "application/pdf"))
        {
            headers.insert("anthropic-beta", HeaderValue::from_static("pdfs-2024-09-25"));
        }

        // Anthropic wants: assistant turns carry `tool_use` blocks, and the matching
        // results come back as `tool_result` blocks inside a single user turn.
        let mut messages_payload: Vec<serde_json::Value> = Vec::new();
        for msg in request.messages {
            match msg.role {
                MessageRole::User => {
                    messages_payload.push(json!({
                        "role": "user",
                        "content": multimodal::anthropic_blocks(&msg.content),
                    }));
                }
                MessageRole::Assistant => {
                    let mut blocks = Vec::new();
                    if !msg.content.text.is_empty() {
                        blocks.push(json!({ "type": "text", "text": msg.content.text }));
                    }
                    for tc in &msg.content.tool_calls {
                        let input = if tc.arguments.is_object() { tc.arguments.clone() } else { json!({}) };
                        blocks.push(json!({
                            "type": "tool_use", "id": tc.call_id, "name": tc.tool_name, "input": input
                        }));
                    }
                    if blocks.is_empty() {
                        continue;
                    }
                    messages_payload.push(json!({ "role": "assistant", "content": blocks }));
                }
                MessageRole::Tool => {
                    let call_id = msg.content.tool_calls.first().map(|t| t.call_id.clone()).unwrap_or_default();
                    let block = json!({
                        "type": "tool_result", "tool_use_id": call_id, "content": msg.content.text
                    });
                    let merge = messages_payload
                        .last()
                        .map(|m| m["role"] == "user" && m["content"].is_array())

                .unwrap_or(false);
            if merge {
                if let Some(arr) = messages_payload.last_mut().and_then(|m| m["content"].as_array_mut()) {
                    arr.push(block);
                }
            } else {
                messages_payload.push(json!({ "role": "user", "content": [block] }));
            }
        }
        MessageRole::System => {}
    }
}

let model_str = if self.label == "github-copilot" {
    request.model.as_str()
} else {
    match request.model.as_str() {
        "odon-auto" | "auto" | "" | "claude-3-7-sonnet" => "claude-3-7-sonnet-20250219",
        "claude-3-5-sonnet" => "claude-3-5-sonnet-20241022",
        "claude-3-5-haiku" => "claude-3-5-haiku-20241022",
        other => other,
    }
};

let mut body = json!({
    "model": model_str,
    "messages": messages_payload,
    "max_tokens": request.max_tokens.unwrap_or(self.default_max_tokens),
    "stream": true,
});

if !request.tools.is_empty() {
    let tools: Vec<_> = request
        .tools
        .iter()
        .map(|t| json!({ "name": t.name, "description": t.description, "input_schema": t.parameters }))
        .collect();
    body["tools"] = json!(tools);
}

if let Some(sys) = request.system_prompt {
    body["system"] = json!(sys);
}

let resp = self
    .client
    .post(&endpoint)
    .headers(headers)
    .json(&body)
    .send()
    .await
    .map_err(|e| OdonError::Provider {
        provider: self.label.clone(),
        message: format!("Anthropic request failed: {}", e),
    })?;

if !resp.status().is_success() {
    let status = resp.status();
    let mut err_body = resp.text().await.unwrap_or_default();
    if err_body.len() > 2000 {
        err_body.truncate(2000);
        err_body.push_str("…");
    }
    return Err(OdonError::Provider {
        provider: self.label.clone(),
        message: format!(
            "HTTP {} from Anthropic (model: {}).{}",
            status.as_u16(),
            model_str,
            if err_body.trim().is_empty() {
                String::new()
            } else {
                format!(" Response: {}", err_body.trim())
            }
        ),
    });
}

let mut stream = resp.bytes_stream().eventsource();

        loop {
            tokio::select! {
                _ = cancellation.cancelled() => {
                    let _ = event_sender.send(StreamEvent::Done).await;
                    return Ok(());
                }
                item = stream.next() => {
                    match item {
                        Some(Ok(event)) => {
                            if event.event == "message_stop" {
                                let _ = event_sender.send(StreamEvent::Done).await;
                                break;
                            }
                            if let Ok(val) = serde_json::from_str::<serde_json::Value>(&event.data) {
                                let evt_type = val.get("type").and_then(|t| t.as_str()).unwrap_or_default();
                                match evt_type {
                                    "content_block_start" => {
                                        if let Some(cb) = val.get("content_block") {
                                            if cb.get("type").and_then(|t| t.as_str()) == Some("tool_use") {
                                                let idx = val.get("index").and_then(|i| i.as_u64()).unwrap_or(0) as usize;
                                                let _ = event_sender.send(StreamEvent::ToolCallDelta {
                                                    index: idx,
                                                    id: cb.get("id").and_then(|s| s.as_str()).map(String::from),
                                                    name: cb.get("name").and_then(|s| s.as_str()).map(String::from),
                                                    arguments_delta: None,
                                                }).await;
                                            }
                                        }
                                    }
                                    "content_block_delta" => {
                                        if let Some(delta) = val.get("delta") {
                                            if let Some(text) = delta.get("text").and_then(|t| t.as_str()) {
                                                let _ = event_sender.send(StreamEvent::TextDelta(text.to_string())).await;
                                            } else if let Some(th) = delta.get("thinking").and_then(|t| t.as_str()) {
                                                let _ = event_sender.send(StreamEvent::ThoughtDelta(th.to_string())).await;
                                            } else if let Some(pj) = delta.get("partial_json").and_then(|t| t.as_str()) {
                                                let idx = val.get("index").and_then(|i| i.as_u64()).unwrap_or(0) as usize;
                                                let _ = event_sender.send(StreamEvent::ToolCallDelta {
                                                    index: idx,
                                                    id: None,
                                                    name: None,
                                                    arguments_delta: Some(pj.to_string()),
                                                }).await;
                                            }
                                        }
                                    }
                                    "message_delta" => {}
                                    "error" => {
                                        let msg = val.get("error").and_then(|e| e.get("message")).and_then(|m| m.as_str()).unwrap_or("Anthropic error");
                                        let _ = event_sender.send(StreamEvent::Error(msg.to_string())).await;
                                        break;
                                    }
                                    _ => {}
                                }
                            }
                        }
                        Some(Err(e)) => {
                            let _ = event_sender.send(StreamEvent::Error(format!("Anthropic stream error: {}", e))).await;
                            break;
                        }
                        None => {
                            let _ = event_sender.send(StreamEvent::Done).await;
                            break;
                        }
                    }
                }
            }
        }

        Ok(())
    }
}

//! Google Antigravity / Gemini Code Assist provider.
//!
//! Speaks the Cloud Code Assist `v1internal` protocol that the Antigravity and
//! Gemini CLI clients use with a Google OAuth bearer token:
//!   1. `:loadCodeAssist` resolves the companion project for the account.
//!   2. `:streamGenerateContent?alt=sse` streams Gemini candidates (text,
//!      thoughts and native function calls).

use async_trait::async_trait;
use base64::Engine;
use eventsource_stream::Eventsource;
use futures_util::StreamExt;
use odon_core::{MessageRole, OdonError, Result};
use reqwest::header::{HeaderMap, HeaderValue, AUTHORIZATION, CONTENT_TYPE, USER_AGENT};
use serde_json::{json, Value};
use tokio::sync::mpsc::Sender;
use tokio_util::sync::CancellationToken;

use crate::multimodal;
use crate::stream::StreamEvent;
use crate::trait_def::{ChatRequest, ModelProvider};

const CODE_ASSIST_HOST: &str = "https://daily-cloudcode-pa.googleapis.com";
const CODE_ASSIST_FALLBACK_HOST: &str = "https://cloudcode-pa.googleapis.com";
/// Google access tokens last ~1h; refresh a little early.
const TOKEN_MAX_AGE: std::time::Duration = std::time::Duration::from_secs(45 * 60);

pub struct AntigravityProvider {
    client: reqwest::Client,
    base_url: String,
    access_token: std::sync::Mutex<(String, std::time::Instant)>,
    project: tokio::sync::Mutex<Option<String>>,
    #[allow(dead_code)]
    account_id: Option<String>,
    signatures: std::sync::Arc<tokio::sync::Mutex<std::collections::HashMap<String, String>>>,
}

fn platform_code() -> i32 {
    if cfg!(target_os = "windows") {
        5
    } else if cfg!(target_os = "macos") {
        2
    } else {
        1
    }
}

fn random_hex(len: usize) -> String {
    let s = format!("{}{}", uuid::Uuid::new_v4().simple(), uuid::Uuid::new_v4().simple());
    s.chars().take(len * 2).collect()
}

fn new_session_id() -> String {
    let bytes = uuid::Uuid::new_v4().into_bytes();
    let num = u64::from_be_bytes(bytes[..8].try_into().unwrap()) & 0x7fff_ffff_ffff_ffff;
    num.to_string()
}

fn antigravity_request_id(message_count: usize) -> String {
    let step = (message_count * 2).max(1) - 1;
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis();
    format!("agent/{}/{}/{}/{}", random_hex(8), now, random_hex(8), step.max(1))
}

fn extract_project_id(raw: &Value) -> Option<String> {
    if let Some(s) = raw.as_str() {
        let trimmed = s.trim().trim_start_matches("projects/").trim();
        if !trimmed.is_empty() {
            return Some(trimmed.to_string());
        }
    }
    if let Some(obj) = raw.as_object() {
        for key in ["id", "projectId", "project", "name"] {
            if let Some(val) = obj.get(key).and_then(|v| v.as_str()) {
                let trimmed = val.trim().trim_start_matches("projects/").trim();
                if !trimmed.is_empty() {
                    return Some(trimmed.to_string());
                }
            }
        }
    }
    None
}

impl AntigravityProvider {
    pub fn new(
        access_token: impl Into<String>,
        account_id: Option<String>,
        custom_base: Option<&str>,
    ) -> Self {
        Self {
            client: reqwest::Client::new(),
            base_url: custom_base.unwrap_or(CODE_ASSIST_HOST).trim_end_matches('/').to_string(),
            access_token: std::sync::Mutex::new((access_token.into(), std::time::Instant::now())),
            project: tokio::sync::Mutex::new(None),
            account_id,
            signatures: std::sync::Arc::new(tokio::sync::Mutex::new(std::collections::HashMap::new())),
        }
    }

    async fn remember_signature(&self, key: &str, signature: &str) {
        if !signature.is_empty() {
            let mut sigs = self.signatures.lock().await;
            sigs.insert(key.to_string(), signature.to_string());
        }
    }

    async fn get_signature(&self, key: &str) -> Option<String> {
        let sigs = self.signatures.lock().await;
        sigs.get(key).cloned()
    }

    async fn token(&self) -> String {
        let (tok, age) = {
            let g = self.access_token.lock().unwrap();
            (g.0.clone(), g.1.elapsed())
        };
        if age > TOKEN_MAX_AGE {
            if let Some(fresh) = crate::host_creds::discover_antigravity().await {
                let mut g = self.access_token.lock().unwrap();
                *g = (fresh.access_token.clone(), std::time::Instant::now());
                return fresh.access_token;
            }
        }
        tok
    }

    fn headers(token: &str, session: Option<&str>) -> Result<HeaderMap> {
        let mut h = HeaderMap::new();
        h.insert(CONTENT_TYPE, HeaderValue::from_static("application/json"));
        h.insert(
            AUTHORIZATION,
            HeaderValue::from_str(&format!("Bearer {token}")).map_err(|e| OdonError::Auth(e.to_string()))?,
        );
        let platform = if cfg!(target_os = "windows") { "windows/x64" } else if cfg!(target_os = "macos") { "darwin/arm64" } else { "linux/x64" };
        h.insert(USER_AGENT, HeaderValue::from_str(&format!("antigravity/ide/2.11.0 {platform}")).unwrap_or(HeaderValue::from_static("antigravity/ide/2.11.0 windows/x64")));
        if let Some(s) = session {
            if let Ok(v) = HeaderValue::from_str(s) {
                h.insert("x-machine-session-id", v);
            }
        }
        Ok(h)
    }

async fn project_id(&self, token: &str) -> Result<String> {
    let mut cached = self.project.lock().await;
    if let Some(p) = cached.as_ref() {
        if !p.starts_with("termixgo-") {
            return Ok(p.clone());
        }
    }
    if let Some(acc) = &self.account_id {
        let trimmed = acc.trim().trim_start_matches("projects/").trim();
        if !trimmed.is_empty() {
            *cached = Some(trimmed.to_string());
            return Ok(trimmed.to_string());
        }
    }

    let metadata = json!({
        "ideType": 9,
        "platform": platform_code(),
        "pluginType": 2
    });

    // 1. Query loadCodeAssist with IDE metadata (matching Termigo)
    let load_url = format!("{}/v1internal:loadCodeAssist", CODE_ASSIST_FALLBACK_HOST);
    let resp = self
        .client
        .post(&load_url)
        .headers(Self::headers(token, None)?)
        .json(&json!({ "metadata": metadata }))
        .send()
        .await;

    if let Ok(res) = resp {
        if res.status() == 401 {
            return Err(OdonError::Auth("Antigravity token expired or invalid".into()));
        }
        if res.status().is_success() {
            let val: Value = res.json().await.unwrap_or(Value::Null);
            tracing::info!("Antigravity loadCodeAssist raw response: {:?}", val);
            if let Some(proj) = val.get("cloudaicompanionProject")
                .and_then(extract_project_id)
                .or_else(|| val.get("project").and_then(extract_project_id))
                .or_else(|| val.get("projectId").and_then(extract_project_id))
            {
                tracing::info!("Antigravity companion project found: {}", proj);
                *cached = Some(proj.clone());
                return Ok(proj);
            }

            // If not yet onboarded, check default tier from allowedTiers
            let mut tier = "legacy-tier".to_string();
            if let Some(tiers) = val.get("allowedTiers").and_then(|t| t.as_array()) {
                for candidate in tiers {
                    if candidate.get("isDefault").and_then(|d| d.as_bool()).unwrap_or(false) {
                        if let Some(id) = candidate.get("id").and_then(|i| i.as_str()) {
                            tier = id.to_string();
                            break;
                        }
                    }
                }
            }

            // 2. Call onboardUser (matching Termigo)
            let onboard_url = format!("{}/v1internal:onboardUser", CODE_ASSIST_FALLBACK_HOST);
            for _ in 0..3 {
                let onboard_resp = self
                    .client
                    .post(&onboard_url)
                    .headers(Self::headers(token, None)?)
                    .json(&json!({ "tierId": tier, "metadata": metadata }))
                    .send()
                    .await;

                if let Ok(onboard_res) = onboard_resp {
                    if onboard_res.status().is_success() {
                        let onboard_val: Value = onboard_res.json().await.unwrap_or(Value::Null);
                        let from_onboard = onboard_val.get("response")
                            .and_then(|r| r.get("cloudaicompanionProject"))
                            .and_then(extract_project_id)
                            .or_else(|| onboard_val.get("cloudaicompanionProject").and_then(extract_project_id))
                            .or_else(|| onboard_val.get("response").and_then(extract_project_id));

                            if let Some(proj) = from_onboard {
                                *cached = Some(proj.clone());
                                return Ok(proj);
                            }
                            if onboard_val.get("done").and_then(|d| d.as_bool()).unwrap_or(false) {
                                break;
                            }
                        }
                    }
                    tokio::time::sleep(tokio::time::Duration::from_secs(2)).await;
                }
            }
        }

        // 3. Fallback project format matching Termigo
        let fallback = format!("termixgo-{}", random_hex(4));
        *cached = Some(fallback.clone());
        Ok(fallback)
    }
}

/// Gemini function declarations reject several JSON-Schema keywords and require that
/// every field in `required` exists in `properties`.
fn sanitize_schema(v: &Value) -> Value {
    match v {
        Value::Object(m) => {
            let mut out = serde_json::Map::new();
            for (k, val) in m {
                if matches!(
                    k.as_str(),
                    "default"
                        | "additionalProperties"
                        | "$schema"
                        | "$id"
                        | "$ref"
                        | "$defs"
                        | "definitions"
                        | "examples"
                        | "title"
                        | "optional"
                        | "deprecated"
                        | "readOnly"
                        | "writeOnly"
                ) {
                    continue;
                }
                out.insert(k.clone(), sanitize_schema(val));
            }

            // Prune required fields that are not in properties
            if let Some(req_val) = out.get("required") {
                if let Some(req_arr) = req_val.as_array() {
                    let props = out.get("properties").and_then(|p| p.as_object());
                    let filtered: Vec<Value> = req_arr
                        .iter()
                        .filter(|item| {
                            if let Some(prop_name) = item.as_str() {
                                if let Some(p) = props {
                                    return p.contains_key(prop_name);
                                }
                            }
                            false
                        })
                        .cloned()
                        .collect();

                    if filtered.is_empty() {
                        out.remove("required");
                    } else {
                        out.insert("required".to_string(), Value::Array(filtered));
                    }
                }
            }

            Value::Object(out)
        }
        Value::Array(a) => Value::Array(a.iter().map(sanitize_schema).collect()),
        other => other.clone(),
    }
}

#[async_trait]
impl ModelProvider for AntigravityProvider {
    fn provider_name(&self) -> &str {
        "antigravity"
    }

    async fn stream_chat(
        &self,
        request: ChatRequest,
        event_sender: Sender<StreamEvent>,
        cancellation: CancellationToken,
    ) -> Result<()> {
        let token = self.token().await;
        let project = self.project_id(&token).await?;

        let mut contents: Vec<Value> = Vec::new();
        for msg in &request.messages {
            match msg.role {
                MessageRole::User => contents.push(json!({
                    "role": "user",
                    "parts": multimodal::gemini_parts(&msg.content),
                })),
                MessageRole::Assistant => {
                    let mut parts = Vec::new();
                    if !msg.content.text.is_empty() {
                        parts.push(json!({ "text": msg.content.text }));
                    }
                    for tc in &msg.content.tool_calls {
                        let args = if tc.arguments.is_object() { tc.arguments.clone() } else { json!({}) };
                        let clean_name = tc.tool_name
                            .trim_start_matches("defaultapi:")
                            .trim_start_matches("default_api:");

                        let sig = self.get_signature(&tc.call_id).await
                            .or(self.get_signature(&tc.tool_name).await)
                            .or(self.get_signature(clean_name).await)
                            .unwrap_or_else(|| {
                                base64::engine::general_purpose::STANDARD.encode(format!("sig_{}_{}", clean_name, tc.call_id))
                            });

                        parts.push(json!({
                            "thoughtSignature": sig,
                            "functionCall": {
                                "id": tc.call_id,
                                "name": clean_name,
                                "args": args
                            }
                        }));
                    }
                    if !parts.is_empty() {
                        contents.push(json!({ "role": "model", "parts": parts }));
                    }
                }
                MessageRole::Tool => {
                    let raw_name = msg.content.tool_calls.first().map(|t| t.tool_name.clone()).unwrap_or_default();
                    let clean_name = raw_name
                        .trim_start_matches("defaultapi:")
                        .trim_start_matches("default_api:");
                    let call_id = msg.content.tool_calls.first().map(|t| t.call_id.clone()).unwrap_or_default();

            let output: Value = serde_json::from_str(&msg.content.text).unwrap_or_else(|_| json!(msg.content.text));
            let mut resp_obj = json!({
                "name": clean_name,
                "response": { "output": output }
            });
            if !call_id.is_empty() {
                resp_obj["id"] = json!(call_id);
            }
            let part = json!({ "functionResponse": resp_obj });
            let merge = contents
                .last()
                .map(|c| c["role"] == "user" && c["parts"].as_array().map(|p| p.iter().all(|x| x.get("functionResponse").is_some())).unwrap_or(false))
                .unwrap_or(false);
            if merge {
                if let Some(arr) = contents.last_mut().and_then(|c| c["parts"].as_array_mut()) {
                    arr.push(part);
                }
            } else {
                contents.push(json!({ "role": "user", "parts": [part] }));
            }
        }
        MessageRole::System => {}
    }
}

let mut inner = json!({ "contents": contents });
if let Some(sys) = &request.system_prompt {
    inner["systemInstruction"] = json!({ "role": "user", "parts": [{ "text": sys }] });
}
if !request.tools.is_empty() {
    let decls: Vec<Value> = request
        .tools
        .iter()
        .map(|t| json!({ "name": t.name, "description": t.description, "parameters": sanitize_schema(&t.parameters) }))
        .collect();
    inner["tools"] = json!([{ "functionDeclarations": decls }]);
}
let session_id = new_session_id();
let wire_model = match request.model.as_str() {
    // Legacy aliases kept so saved sessions keep working.
    "gemini-4-argon" | "gemini-3.1-pro" | "gemini-3.8-flash" | "gemini-3.8-flash-medium" => "gemini-2.5-pro",
    "gemini-3.8-flash-high" | "odon-auto" | "auto" | "" => "gemini-2.5-flash",
    "claude-sonnet-5-5" | "claude-sonnet-4-6" => "claude-sonnet-4-20250514",
    "claude-opus-5-5" => "claude-opus-4-20250514",
    "claude-3-5-sonnet" | "claude-3-5-sonnet-20241022" => "claude-3-5-sonnet-20241022",
    other => other,
};

let mut gen = json!({
    "maxOutputTokens": 64000,
    "thinkingConfig": {
        "includeThoughts": true,
        "thinkingLevel": "medium"
    }
});
if let Some(t) = request.temperature {
    gen["temperature"] = json!(t);
}
if let Some(effort) = &request.effort {
    gen["thinkingConfig"]["thinkingBudget"] = json!(match effort.as_str() { "low" => 2048, "medium" => 8192, "high" => 24576, "xhigh" => 32768, _ => 8192 });
}

let mut inner = json!({
    "contents": contents,
    "sessionId": session_id,
    "generationConfig": gen,
    "safetySettings": [
        { "category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE" },
        { "category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE" },
        { "category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE" },
        { "category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE" },
        { "category": "HARM_CATEGORY_CIVIC_INTEGRITY", "threshold": "BLOCK_NONE" }
    ]
});

if let Some(sys) = &request.system_prompt {
    inner["systemInstruction"] = json!({ "role": "user", "parts": [{ "text": sys }] });
}
if !request.tools.is_empty() {
    let decls: Vec<Value> = request
        .tools
        .iter()
        .map(|t| json!({ "name": t.name, "description": t.description, "parameters": sanitize_schema(&t.parameters) }))
        .collect();
    inner["tools"] = json!([{ "functionDeclarations": decls }]);
    inner["toolConfig"] = json!({ "functionCallingConfig": { "mode": "VALIDATED" } });
}

let body = json!({
    "project": project,
    "model": wire_model,
    "userAgent": "antigravity",
    "requestId": antigravity_request_id(request.messages.len()),
    "request": inner,
});

tracing::info!("Antigravity stream_chat request: project={}, model={}, wire_model={}", project, request.model, wire_model);

let endpoint = format!("{}/v1internal:streamGenerateContent?alt=sse", self.base_url);
let mut resp = self
    .client
    .post(&endpoint)
    .headers(Self::headers(&token, Some(&session_id))?)
    .json(&body)
    .send()
    .await
    .map_err(|e| OdonError::Provider { provider: "antigravity".into(), message: format!("Antigravity request failed: {e}") })?;

if resp.status().is_server_error() && self.base_url.contains("daily-cloudcode-pa") {
    let fallback_url = format!("{}/v1internal:streamGenerateContent?alt=sse", CODE_ASSIST_FALLBACK_HOST);
    if let Ok(retry) = self
        .client
        .post(&fallback_url)
        .headers(Self::headers(&token, Some(&session_id))?)
        .json(&body)
        .send()
        .await
    {
        resp = retry;
    }
}

if resp.status() == 401 {
    return Err(OdonError::Auth("Antigravity token expired or invalid".into()));
}
if !resp.status().is_success() {
    let status = resp.status();
    let err_body = resp.text().await.unwrap_or_default();
    return Err(OdonError::Provider { provider: "antigravity".into(), message: format!("Antigravity HTTP {status}: {err_body}") });
}

let mut stream = resp.bytes_stream().eventsource();
let mut tool_index = 0usize;
loop {
    tokio::select! {
        _ = cancellation.cancelled() => {
            let _ = event_sender.send(StreamEvent::Done).await;
            return Ok(());
        }
        item = stream.next() => match item {
            Some(Ok(ev)) => {
                let Ok(val) = serde_json::from_str::<Value>(&ev.data) else { continue };
                let root = val.get("response").unwrap_or(&val);
                let parts = root
                    .get("candidates")
                    .and_then(|c| c.get(0))
                    .and_then(|c| c.get("content"))
                    .and_then(|c| c.get("parts"))
                    .and_then(|p| p.as_array());
                for part in parts.into_iter().flatten() {
                    if let Some(fc) = part.get("functionCall") {
                        let raw_name = fc.get("name").and_then(|n| n.as_str()).unwrap_or_default().to_string();
                        let name = raw_name
                            .trim_start_matches("defaultapi:")

                                    .trim_start_matches("default_api:")
                                    .to_string();
                                let args = fc.get("args").cloned().unwrap_or_else(|| json!({}));
                                let call_id = fc.get("id").and_then(|i| i.as_str())
                                    .map(String::from)
                                    .unwrap_or_else(|| format!("call_{}_{}", name, uuid::Uuid::new_v4().simple()));

                                let sig = part.get("thoughtSignature")
                                    .or_else(|| part.get("thought_signature"))
                                    .or_else(|| fc.get("thoughtSignature"))
                                    .or_else(|| fc.get("thought_signature"))
                                    .and_then(|s| s.as_str())
                                    .unwrap_or_default();

                                if !sig.is_empty() {
                                    self.remember_signature(&call_id, sig).await;
                                    self.remember_signature(&name, sig).await;
                                    self.remember_signature(&raw_name, sig).await;
                                }

                                let _ = event_sender.send(StreamEvent::ToolCallDelta {
                                    index: tool_index,
                                    id: Some(call_id),
                                    name: Some(name),
                                    arguments_delta: Some(args.to_string()),
                                }).await;
                                tool_index += 1;
                            } else if let Some(text) = part.get("text").and_then(|t| t.as_str()) {
                                if part.get("thought").and_then(|t| t.as_bool()).unwrap_or(false) {
                                    let _ = event_sender.send(StreamEvent::ThoughtDelta(text.to_string())).await;
                                } else {
                                    let _ = event_sender.send(StreamEvent::TextDelta(text.to_string())).await;
                                }
                            }
                        }
                    }
                    Some(Err(e)) => {
                        let _ = event_sender.send(StreamEvent::Error(format!("Antigravity stream error: {e}"))).await;
                        break;
                    }
                    None => {
                        let _ = event_sender.send(StreamEvent::Done).await;
                        break;
                    }
                }
            }
        }
        Ok(())
    }
}

