#[async_trait]
impl Tool for FileChecksumTool {
    fn name(&self) -> &str { "file_checksum" }
    fn description(&self) -> &str { "Verify a workspace file matches an expected SHA-256 checksum" }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
