                <span>Copy</span>
              </>
            )}
          </button>
        </div>
      </div>

      {/* Code Area */}
      <div className="flex-1 overflow-auto bg-slate-50/50 p-3 leading-relaxed">
        <table className="w-full border-collapse">
          <tbody>
            {lines.map((line, i) => (
              <tr key={i} className="hover:bg-blue-50/40">
                <td className="w-9 text-right pr-4 select-none text-slate-400 text-xs align-top">
                  {i + 1}
                </td>
                <td className="whitespace-pre overflow-x-visible align-top font-mono">
                  {renderSyntaxLine(line)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Editor Footer */}
      <div className="h-6 bg-white border-t border-slate-200 px-3 flex items-center justify-between text-[11px] text-slate-500 shrink-0 font-sans">
        <span className="truncate">{currentFile.path}</span>
        <div className="flex items-center gap-3">
          <span className="uppercase">{currentFile.language}</span>
          <span>UTF-8</span>
        </div>
      </div>
    </div>
  );
}

function renderSyntaxLine(line: string) {
  if (line.trim().startsWith('//')) {
    return <span className="text-emerald-600 italic">{line}</span>;
  }

  const tokens = line.split(/(\b(?:import|from|export|default|function|const|let|return|interface|type)\b|'[^']*'|"[^"]*"|`[^`]*`)/g);

  return (
    <span>
      {tokens.map((token, idx) => {
        if (/^(import|from|export|default|function|const|let|return|interface|type)$/.test(token)) {
          return <span key={idx} className="text-blue-700 font-semibold">{token}</span>;
        }
        if (/^['"`]/.test(token)) {
          return <span key={idx} className="text-amber-700">{token}</span>;
        }
        if (/^[A-Z][a-zA-Z0-9]+/.test(token)) {
          return <span key={idx} className="text-teal-700 font-medium">{token}</span>;
        }
        return <span key={idx} className="text-slate-700">{token}</span>;
      })}
    </span>
  );
}

import React, { useState, useEffect } from 'react';
import {
  Folder,
  FolderOpen,
  File,
  FileCode,
  FileText,
  FileJson,
  Image as ImageIcon,
  ChevronRight,
  ChevronDown,
  RefreshCw,
  Plus,
  Trash2,
  Save,
  Search,
  ExternalLink,
  MessageSquare,
  Copy,
  Check,
  X,
  FilePlus,
  FolderPlus,
  ArrowUp,
} from 'lucide-react';
import { api, FsEntryItem, FsReadResult } from '../api';

interface FileExplorerViewProps {
  onAskAiAboutFile?: (path: string, content: string) => void;
  onOpenInTerminal?: (path: string) => void;
}

export const FileExplorerView: React.FC<FileExplorerViewProps> = ({
  onAskAiAboutFile,
  onOpenInTerminal,
}) => {
  const [currentPath, setCurrentPath] = useState<string>('.');
  const [entries, setEntries] = useState<FsEntryItem[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [searchQuery, setSearchQuery] = useState<string>('');

  // Selected file and its content
  const [selectedFile, setSelectedFile] = useState<string | null>(null);
  const [fileData, setFileData] = useState<FsReadResult | null>(null);
  const [editedContent, setEditedContent] = useState<string>('');
  const [isSaving, setIsSaving] = useState<boolean>(false);
  const [saveSuccess, setSaveSuccess] = useState<boolean>(false);
  const [copiedPath, setCopiedPath] = useState<boolean>(false);

  // Modal for new file / new folder
  const [createModal, setCreateModal] = useState<'file' | 'folder' | null>(null);
  const [newItemName, setNewItemName] = useState<string>('');

  const loadDirectory = async (path: string) => {
    setIsLoading(true);
    try {
      const res = await api.fsList(path);
      setEntries(res.entries || []);
      setCurrentPath(path);
    } catch (err) {
      console.error('Failed to load directory:', err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadDirectory('.');
  }, []);

const handleOpenFile = async (entry: FsEntryItem) => {
  if (entry.is_dir) {
    loadDirectory(entry.path);
  } else {
    setSelectedFile(entry.path);
    try {
      const res = await api.fsRead(entry.path);
      setFileData(res);
      setEditedContent(res.content || '');
    } catch (err) {
      console.error('Failed to read file:', err);
    }
  }
};

const handleGoUp = () => {
  if (currentPath === '.' || !currentPath.includes('/')) {
    loadDirectory('.');
    return;
  }
  const parts = currentPath.split('/');
  parts.pop();
  const parent = parts.join('/') || '.';
  loadDirectory(parent);
};

const handleSaveFile = async () => {
  if (!selectedFile) return;
  setIsSaving(true);
  try {
    const res = await api.fsWrite(selectedFile, editedContent);
    if (res.success) {
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
    }
  } catch (err) {
    console.error('Failed to save file:', err);
  } finally {
    setIsSaving(false);
  }
};

const handleDeleteEntry = async (entry: FsEntryItem, e: React.MouseEvent) => {
  e.stopPropagation();
  if (!confirm(`Are you sure you want to delete ${entry.name}?`)) return;
  try {
    await api.fsDelete(entry.path);
    if (selectedFile === entry.path) {
      setSelectedFile(null);
      setFileData(null);
    }
    loadDirectory(currentPath);
  } catch (err) {
    console.error('Failed to delete path:', err);
  }
};

const handleCreateItem = async () => {
  if (!newItemName.trim() || !createModal) return;
  const target = currentPath === '.' ? newItemName.trim() : `${currentPath}/${newItemName.trim()}`;
  try {
    if (createModal === 'file') {
      await api.fsWrite(target, '');
    } else {
      await api.fsMkdir(target);
    }
    setCreateModal(null);
    setNewItemName('');
    loadDirectory(currentPath);
  } catch (err) {
    console.error('Failed to create item:', err);
  }
};

const handleCopyPath = () => {
  if (!selectedFile) return;
  navigator.clipboard.writeText(selectedFile);
  setCopiedPath(true);
  setTimeout(() => setCopiedPath(false), 1500);
};

const filteredEntries = entries.filter((e) =>
  e.name.toLowerCase().includes(searchQuery.toLowerCase())
);

const getFileIcon = (entry: FsEntryItem) => {
  if (entry.is_dir) return <Folder className="w-4 h-4 text-blue-500 fill-blue-500/20" />;
  const ext = entry.extension?.toLowerCase();
