            </span>
          )}
        </div>

      className={className}
    >
      <path
        d="M4 8.5L8.5 4H15.5L20 8.5V15.5L15.5 20H8.5L4 15.5V8.5Z"
        stroke={colored ? '#FF6A00' : 'currentColor'}
