      />
      <path
        d="M8.5 12H15.5M12 8.5V15.5"
        stroke={colored ? '#FF6A00' : 'currentColor'}
        strokeWidth="2.2"
        strokeLinecap="round"
      />
    </svg>
  );
}

// 6. StepFun / 阶跃星辰 (Official Stepped Geometric Mark)
