  });
  const [effortLevel, setEffortLevel] = useState<string>(() => {
    if (typeof window !== 'undefined') return localStorage.getItem('odon_effort_level') || 'high';
    return 'high';
  });

  // Skills State
  const [skillsList, setSkillsList] = useState<SkillItemInfo[]>([]);
