      </div>

  {/* Profiles List */}
  <div className="flex-1 overflow-y-auto p-2 space-y-1">
    {profiles.length === 0 ? (
      <div className="p-6 text-center text-xs text-neutral-400">
        No SSH hosts configured. Click Add Host above.
      </div>
    ) : (
      profiles.map((p) => {
        const isSelected = selectedProfile?.id === p.id;
        return (
          <div
            key={p.id}
